def serialize_numeric(self, tag):
        """Return the literal representation of a numeric tag."""
        if tag.value is None:
            return 'null'
        if tag.type == 'i4':
            return str(tag.value)
        if tag.type == 'u4':
            return str(tag.value)
        if tag.type == 'double':
            return str(tag.value)
        return ''

